import pandas as pd, numpy as np, sys
pd.set_option("display.width",200); pd.set_option("display.max_columns",30)
S=sys.argv[1]
sh=pd.read_pickle(f"{S}/data/shifts.pkl"); ca=pd.read_pickle(f"{S}/data/cancels.pkl")
P=print
P("### SHIFTS", sh.shape, "unique Shift ID:", sh["Shift ID"].nunique(), "| dup action rows:", sh.duplicated().sum())
P("Start range:", sh.Start.min(), "->", sh.Start.max()); P("Created range:", sh["Created At"].min(), "->", sh["Created At"].max())
P("Deleted values:\n", sh.Deleted.value_counts(dropna=False).to_string())
P("Verified:\n", sh.Verified.value_counts(dropna=False).to_string())
P("Worker ID null:", sh["Worker ID"].isna().sum(), "| Facility null:", sh["Facility ID"].isna().sum())
P("Agent Req:\n", sh["Agent Req"].value_counts(dropna=False).to_string())
P("Shift Type:\n", sh["Shift Type"].value_counts(dropna=False).to_string())
P("Charge by Agent Req:\n", sh.groupby("Agent Req").Charge.describe()[["count","mean","50%","min","max"]].round(1).to_string())
P("Time (hours) describe:\n", sh.Time.describe().round(2).to_string())
P("Unique facilities:", sh["Facility ID"].nunique(), "| unique workers:", sh["Worker ID"].nunique())
fac=sh.groupby("Facility ID").size().sort_values(ascending=False); P("Shifts per facility: top10 share %.1f%%, top5:" % (100*fac.head(10).sum()/fac.sum()), fac.head(5).to_dict())
sh["has_worker"]=sh["Worker ID"].notna(); sh["deleted"]=sh.Deleted.notna()
P("Cross verified x deleted x has_worker:\n", sh.groupby(["Verified","deleted","has_worker"]).size().to_string())
P("Shifts per month (by Start):\n", sh.groupby(sh.Start.dt.to_period("M")).size().to_string())
P("Verified rate by month:\n", sh.groupby(sh.Start.dt.to_period("M")).Verified.mean().round(3).to_string())
P("\n### CANCELS", ca.shape, "unique Action ID:", ca["Action ID"].nunique(), "unique Shift ID:", ca["Shift ID"].nunique())
P("Created range:", ca["Created At"].min(), "->", ca["Created At"].max()); P("Start range:", ca.Start.min(), "->", ca.Start.max())
P("Action:\n", ca.Action.value_counts().to_string())
bins=[-np.inf,0,4,24,72,168,np.inf]; labels=["<0 (after start)","0-4h","4-24h","24-72h","72h-7d",">7d"]
ca["lt_bin"]=pd.cut(ca["Lead Time"],bins=bins,labels=labels,right=False)
P("Lead time bins x Action:\n", pd.crosstab(ca.lt_bin, ca.Action, margins=True).to_string())
P("NCNS lead time describe:\n", ca[ca.Action=="NO_CALL_NO_SHOW"]["Lead Time"].describe().round(2).to_string())
P("WORKER_CANCEL lead time describe:\n", ca[ca.Action=="WORKER_CANCEL"]["Lead Time"].describe().round(2).to_string())
# recompute lead time from timestamps to validate
ca["lt_calc"]=(ca.Start-ca["Created At"]).dt.total_seconds()/3600; P("Lead time vs calc: max abs diff", (ca["Lead Time"]-ca.lt_calc).abs().max().round(3))
P("Cancels per shift id:\n", ca.groupby("Shift ID").size().value_counts().sort_index().to_string())
# join coverage
inshift=ca["Shift ID"].isin(sh["Shift ID"]); P("Cancel rows whose Shift ID in shifts log: %d / %d (%.1f%%)" % (inshift.sum(), len(ca), 100*inshift.mean()))
inrange=(ca.Start>=sh.Start.min())&(ca.Start<=sh.Start.max()); P("Cancel rows with Start in shifts Start range: %.1f%%; of those in shifts log: %.1f%%" % (100*inrange.mean(), 100*inshift[inrange].mean()))
facin=ca["Facility ID"].isin(sh["Facility ID"]); P("Cancel rows w/ facility in shifts: %.1f%%" % (100*facin.mean()), "| cancel facilities:", ca["Facility ID"].nunique(), "| cancel workers:", ca["Worker ID"].nunique())
P("Cancels per month (by Start) x Action:\n", pd.crosstab(ca.Start.dt.to_period("M"), ca.Action).to_string())
late=ca[ca["Lead Time"]<24]
P("\nLATE (<24h incl NCNS) per month:\n", late.groupby(late.Start.dt.to_period("M")).size().to_string())
w=late.groupby("Worker ID").size().sort_values(ascending=False); P("Late cancels per worker: n workers", len(w), "| top10%% share %.1f%% | top20%% share %.1f%% | 1-timers %d" % (100*w.head(int(len(w)*.1)).sum()/w.sum(), 100*w.head(int(len(w)*.2)).sum()/w.sum(), (w==1).sum()))
P("Distribution of late cancels per worker:\n", w.value_counts().sort_index().head(15).to_string())
f=late.groupby("Facility ID").size().sort_values(ascending=False); P("Late cancels per facility: n", len(f), "| top10 share %.1f%%" % (100*f.head(10).sum()/f.sum()))
P("Late cancels by shift start hour:\n", late.groupby(late.Start.dt.hour).size().to_string())
P("Late cancels by weekday:\n", late.groupby(late.Start.dt.dayofweek).size().to_string())
P("Cancel Created At hour-of-day (all cancels):\n", ca.groupby(ca["Created At"].dt.hour).size().to_string())
